internal static class SystemMonitorLayoutMath{internal static double NaturalHeight(double value)=>Math.Max(96,Math.Ceiling(double.IsFinite(value)?value:96));internal static bool KeepTop(CanvasItem item,double desired){var height=NaturalHeight(desired);if(Math.Abs(item.Height-height)<.5)return false;var top=item.CenterY-item.Height/2;item.Height=height;item.CenterY=top+height/2;return true;}}
internal sealed class SystemMonitorItemContent:IDesktopItemContent{
 private readonly CanvasItem item;private readonly ISystemMetricsService service;private readonly Border root;private readonly StackPanel stack=new();private readonly Border divider=new(){Height=1,Margin=new Thickness(0,8,0,8)};private readonly Row cpu=new("CPU"),ram=new("RAM"),gpu=new("GPU");private readonly Net down=new("↓  DOWNLOAD"),up=new("↑  UPLOAD");private IDisposable? lease;private bool active;
 internal SystemMonitorItemContent(CanvasItem item,ISystemMetricsService service){this.item=item;this.service=service;var header=new TextBlock{Text="◇  SYSTEM STATUS",FontSize=10,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,12)};stack.Children.Add(header);stack.Children.Add(cpu.View);stack.Children.Add(ram.View);stack.Children.Add(gpu.View);stack.Children.Add(divider);stack.Children.Add(down.View);stack.Children.Add(up.View);stack.UseLayoutRounding=true;stack.SnapsToDevicePixels=true;root=WidgetTheme.Card(item,stack);root.UseLayoutRounding=true;root.SnapsToDevicePixels=true;Update(service.Snapshot);}
 public UIElement View=>root;public void SetActive(bool value){if(active==value)return;active=value;if(value){service.SnapshotChanged+=Changed;SystemEvents.UserPreferenceChanged+=ThemeChanged;lease=service.Acquire();Update(service.Snapshot);}else{service.SnapshotChanged-=Changed;SystemEvents.UserPreferenceChanged-=ThemeChanged;lease?.Dispose();lease=null;cpu.Stop();ram.Stop();gpu.Stop();}}internal void Refresh()=>Update(service.Snapshot);public void Dispose(){SetActive(false);cpu.Dispose();ram.Dispose();gpu.Dispose();}private void Changed(object? _,SystemMetricsSnapshot value)=>root.Dispatcher.BeginInvoke(()=>Update(value));private void ThemeChanged(object? _,UserPreferenceChangedEventArgs __)=>root.Dispatcher.BeginInvoke(()=>Update(service.Snapshot));
 private void Update(SystemMetricsSnapshot value){var p=WidgetTheme.Resolve(item);WidgetTheme.Apply(root,p);var accent=new[]{WidgetTheme.Blend(p.Accent,WpfColor.FromRgb(105,188,255),.72),WidgetTheme.Blend(p.Accent,WpfColor.FromRgb(111,219,174),.72),WidgetTheme.Blend(p.Accent,WpfColor.FromRgb(195,145,255),.72)};((TextBlock)stack.Children[0]).Foreground=new SolidColorBrush(p.Muted);cpu.Update(value.Cpu,Clock(),accent[0],p,active);ram.Update(value.Memory,Aux(value.Memory),accent[1],p,active);gpu.Update(value.Gpu,Aux(value.Gpu),accent[2],p,active);down.Update(value.Download,accent[0],p);up.Update(value.Upload,WidgetTheme.Blend(p.Accent,WpfColor.FromRgb(255,116,116),.76),p);cpu.View.Visibility=item.SystemMonitor.ShowCpu?Visibility.Visible:Visibility.Collapsed;ram.View.Visibility=item.SystemMonitor.ShowMemory?Visibility.Visible:Visibility.Collapsed;gpu.View.Visibility=item.SystemMonitor.ShowGpu?Visibility.Visible:Visibility.Collapsed;down.View.Visibility=up.View.Visibility=item.SystemMonitor.ShowNetwork?Visibility.Visible:Visibility.Collapsed;divider.Visibility=(item.SystemMonitor.ShowCpu||item.SystemMonitor.ShowMemory||item.SystemMonitor.ShowGpu)&&item.SystemMonitor.ShowNetwork?Visibility.Visible:Visibility.Collapsed;divider.Background=new SolidColorBrush(WpfColor.FromArgb(55,p.Foreground.R,p.Foreground.G,p.Foreground.B));root.Measure(new Size(item.Width,double.PositiveInfinity));SystemMonitorLayoutMath.KeepTop(item,root.DesiredSize.Height);}
 private static string Aux(MetricValue value){if(value.Availability!=MetricAvailability.Available)return value.Availability==MetricAvailability.Loading?"…":"--";var split=value.Text.IndexOf("  ",StringComparison.Ordinal);return split>=0?value.Text[(split+2)..]:value.Text;}private static string Clock(){try{var data=new Power[Math.Max(1,Environment.ProcessorCount)];return CallNtPowerInformation(11,IntPtr.Zero,0,data,Marshal.SizeOf<Power>()*data.Length)==0?SystemMetricMath.FormatProcessorClock(data.Select(x=>x.Current)):"-- GHz";}catch{return "-- GHz";}}[StructLayout(LayoutKind.Sequential)]private struct Power{public uint N,Max,Current,Limit,MaxIdle,Idle;}[DllImport("powrprof.dll")]private static extern uint CallNtPowerInformation(int level,IntPtr input,int inputLength,[Out]Power[] output,int outputLength);
 private sealed class Row{private readonly TextBlock label,percent=new(){FontWeight=FontWeights.SemiBold,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center},detail=new(){FontSize=12,VerticalAlignment=VerticalAlignment.Center};private readonly Ellipse track=new(){Width=60,Height=60,StrokeThickness=5};private readonly WpfPath arc=new(){StrokeThickness=5,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round};private readonly ValueHost value;internal Grid View{get;}internal Row(string name){label=new TextBlock{Text=name,FontSize=14,VerticalAlignment=VerticalAlignment.Center};value=new ValueHost(v=>arc.Data=Arc(v));var dial=new Grid{Width=60,Height=60};dial.Children.Add(track);dial.Children.Add(arc);dial.Children.Add(percent);View=new Grid{Height=68};View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(72)});View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(64)});View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});View.Children.Add(label);Grid.SetColumn(dial,1);View.Children.Add(dial);Grid.SetColumn(detail,2);View.Children.Add(detail);}internal void Update(MetricValue metric,string text,WpfColor color,WidgetPalette p,bool animate){var m=new SolidColorBrush(p.Muted);label.Foreground=detail.Foreground=m;percent.Foreground=new SolidColorBrush(p.Foreground);track.Stroke=new SolidColorBrush(WpfColor.FromArgb(48,p.Foreground.R,p.Foreground.G,p.Foreground.B));arc.Stroke=metric.Availability==MetricAvailability.Available?new SolidColorBrush(color):new SolidColorBrush(WpfColor.FromRgb(115,115,124));percent.Text=metric.Availability==MetricAvailability.Available?$"{metric.Value:0}%":metric.Availability==MetricAvailability.Loading?"…":"--";detail.Text=text;if(metric.Availability==MetricAvailability.Available)value.Set(SystemMetricRingMath.Clamp(metric.Value??0),animate);else value.Clear();}internal void Stop()=>value.Stop();internal void Dispose()=>value.Dispose();private static Geometry Arc(double x){if(x<=0)return Geometry.Empty;var r=Math.Min(359.99,x*3.6)*Math.PI/180;const double radius=27.5;var end=new Point(30+radius*Math.Sin(r),30-radius*Math.Cos(r));return new PathGeometry([new PathFigure{StartPoint=new Point(30,2.5),Segments={new ArcSegment{Point=end,Size=new Size(radius,radius),IsLargeArc=r>Math.PI,SweepDirection=SweepDirection.Clockwise}}}]);}}
 private sealed class ValueHost:Animatable{private readonly Action<double> sink;internal ValueHost(Action<double> sink)=>this.sink=sink;internal static readonly DependencyProperty VProperty=DependencyProperty.Register(nameof(V),typeof(double),typeof(ValueHost),new PropertyMetadata(0d,(o,e)=>((ValueHost)o).sink(SystemMetricRingMath.Clamp((double)e.NewValue))));internal double V{get=>(double)GetValue(VProperty);set=>SetValue(VProperty,value);}internal void Set(double to,bool animate){var from=V;BeginAnimation(VProperty,null);if(!animate){V=to;return;}var a=new DoubleAnimation(from,to,TimeSpan.FromMilliseconds(700)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut},FillBehavior=FillBehavior.Stop};BeginAnimation(VProperty,a);V=to;}internal void Clear(){BeginAnimation(VProperty,null);V=0;}internal void Stop()=>BeginAnimation(VProperty,null);internal void Dispose()=>Stop();protected override Freezable CreateInstanceCore()=>new ValueHost(sink);}
 private sealed class Net{private readonly TextBlock label,value=new(){FontSize=12,HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Center};private readonly WpfPath graph=new(){StrokeThickness=1.6,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round};private readonly NetworkHistory history=new(30);internal Grid View{get;}internal Net(string name){label=new TextBlock{Text=name,FontSize=12,VerticalAlignment=VerticalAlignment.Center};View=new Grid{Height=40};View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(100)});View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(90)});View.Children.Add(label);Grid.SetColumn(graph,1);View.Children.Add(graph);Grid.SetColumn(value,2);View.Children.Add(value);}internal void Update(MetricValue m,WpfColor color,WidgetPalette p){var brush=new SolidColorBrush(color);label.Foreground=value.Foreground=new SolidColorBrush(p.Muted);graph.Stroke=brush;value.Text=m.Text;history.Add(m.Value??0);var points=NetworkGraphMath.Points(history.Normalized());if(points.Count==0){graph.Data=Geometry.Empty;return;}var f=new PathFigure{StartPoint=points[0]};foreach(var x in points.Skip(1))f.Segments.Add(new LineSegment(x,true));graph.Data=new PathGeometry([f]);}}
}
internal static class SystemMetricRingMath{internal static double Clamp(double x)=>double.IsFinite(x)?Math.Clamp(x,0,100):0;internal static double CubicEaseOut(double from,double to,double progress){var t=Math.Clamp(progress,0,1);return from+(to-from)*(1-Math.Pow(1-t,3));}}
